parts.openscad_module:
$fn = 96;

nema_face_size     = 42.3;
nema_bolt_circle   = 31;
nema_shaft_boss_d  = 22;
nema_bolt_hole_d   = 3.4;
plate_size         = 60;
plate_thickness    = 5;
edge_margin        = (plate_size - nema_face_size) / 2;

module nema17_motor_mount() {
  difference() {
    cube([plate_size, plate_size, plate_thickness], center = true);
    cylinder(h = plate_thickness + 2, d = nema_shaft_boss_d, center = true, $fn = 64);
    for (x = [-nema_bolt_circle/2, nema_bolt_circle/2])
      for (y = [-nema_bolt_circle/2, nema_bolt_circle/2])
        translate([x, y, 0])
          cylinder(h = plate_thickness + 2, d = nema_bolt_hole_d, center = true, $fn = 32);
  }
}

nema17_motor_mount();

$fn = 96;

base_length = 95;
base_width = 75;
face_width = 75;
face_height = 82;
plate_thickness = 6;
corner_chamfer = 8;

nema23_face_size = 57.3;
nema23_bolt_spacing = 47.1;
motor_hole_d = 5.5;
shaft_clearance_d = 38;

base_slot_length = 55;
base_slot_d = 6.0;
base_slot_spacing = 42;
gusset_depth = 6;
gusset_run = 48;

module rounded_slot(length, diameter, height) {
  hull() {
    translate([-length/2 + diameter/2, 0, 0])
      cylinder(h = height, d = diameter, center = true, $fn = 40);
    translate([ length/2 - diameter/2, 0, 0])
      cylinder(h = height, d = diameter, center = true, $fn = 40);
  }
}

module chamfered_face_plate_2d(width, height, chamfer) {
  polygon(points = [
    [-width/2 + chamfer, 0],
    [ width/2 - chamfer, 0],
    [ width/2, chamfer],
    [ width/2, height],
    [-width/2, height],
    [-width/2, chamfer]
  ]);
}

module nema23_l_motor_mount() {
  difference() {
    union() {
      // Horizontal base plate: X length, Y width, Z thickness.
      translate([0, 0, plate_thickness/2])
        cube([base_length, base_width, plate_thickness], center = true);

      // Vertical motor face plate: X thickness, Y width, Z height.
      translate([-base_length/2 + plate_thickness/2, 0, face_height/2])
        rotate([90, 0, 90])
          linear_extrude(height = plate_thickness, center = true)
            chamfered_face_plate_2d(face_width, face_height, corner_chamfer);

      // Two triangular side gussets like the photo, near the side edges.
      for (y = [-base_width/2 + gusset_depth/2, base_width/2 - gusset_depth/2])
        translate([-base_length/2 + plate_thickness, y, plate_thickness])
          rotate([90, 0, 0])
            linear_extrude(height = gusset_depth, center = true)
              polygon(points = [[0, 0], [gusset_run, 0], [0, gusset_run]]);
    }

    // Large centered motor shaft / boss clearance through vertical face along X.
    translate([-base_length/2 + plate_thickness/2, 0, face_height/2])
      rotate([0, 90, 0])
        cylinder(h = plate_thickness + 2, d = shaft_clearance_d, center = true, $fn = 96);

    // NEMA23 four-hole square bolt pattern through vertical face along X.
    for (y = [-nema23_bolt_spacing/2, nema23_bolt_spacing/2])
      for (z = [face_height/2 - nema23_bolt_spacing/2, face_height/2 + nema23_bolt_spacing/2])
        translate([-base_length/2 + plate_thickness/2, y, z])
          rotate([0, 90, 0])
            cylinder(h = plate_thickness + 2, d = motor_hole_d, center = true, $fn = 40);

    // Two long rounded mounting slots through base along Z.
    for (y = [-base_slot_spacing/2, base_slot_spacing/2])
      translate([base_length*0.12, y, plate_thickness/2])
        rounded_slot(base_slot_length, base_slot_d, plate_thickness + 2);
  }
}

nema23_l_motor_mount();

$fn = 96;

leg_a_length    = 50;
leg_b_length    = 50;
bracket_width   = 30;
plate_thickness = 4;
hole_d          = 5.5;
edge_margin     = 12;

module l_bracket() {
  difference() {
    union() {
      // Base plate: length along X, width along Y, thickness along Z.
      translate([0, 0, plate_thickness/2])
        cube([leg_a_length, bracket_width, plate_thickness], center = true);

      // Upright plate: thickness along X, width along Y, height along Z.
      translate([-leg_a_length/2 + plate_thickness/2, 0, leg_b_length/2])
        cube([plate_thickness, bracket_width, leg_b_length], center = true);
    }

    // Four base holes pass through Z.
    for (x = [-leg_a_length/2 + edge_margin, leg_a_length/2 - edge_margin])
      for (y = [-bracket_width/2 + edge_margin, bracket_width/2 - edge_margin])
        translate([x, y, plate_thickness/2])
          cylinder(h = plate_thickness + 2, d = hole_d, center = true, $fn = 40);

    // Four upright holes pass through X, not Z.
    for (z = [edge_margin, leg_b_length - edge_margin])
      for (y = [-bracket_width/2 + edge_margin, bracket_width/2 - edge_margin])
        translate([-leg_a_length/2 + plate_thickness/2, y, z])
          rotate([0, 90, 0])
            cylinder(h = plate_thickness + 2, d = hole_d, center = true, $fn = 40);
  }
}

l_bracket();
